"""Metadata only for the configured secret reference; never open its content."""
import hashlib,json,os,re,signal,stat,sys,types
from pathlib import Path
BINDING_SOURCE=b'"""Observe private config/output correspondence, never accept writer authority."""\nimport ast, hashlib, json, os, re, signal, stat, subprocess, sys, types\nfrom pathlib import Path\nOBSERVER_SOURCE=b\'"""Untrusted static observation only; never authenticate or execute the producer."""\\nimport ast, hashlib, json, os, re, shlex, signal, stat, subprocess\\nfrom pathlib import Path\\n\\nTARGET = Path(\\\'/opt/ouf/ops/refresh-policy-token.py\\\')\\nEXPECTED = {\\\'/opt\\\': (0, 0, 0o755), \\\'/opt/ouf\\\': (1000, 1000, 0o750),\\n            \\\'/opt/ouf/ops\\\': (0, 0, 0o700)}\\nPUBLIC_KEYS = {\\\'grant_type\\\', \\\'client_id\\\', \\\'client_secret\\\', \\\'access_token\\\',\\n               \\\'expires_in\\\', \\\'token_type\\\', \\\'scope\\\', \\\'Authorization\\\', \\\'Content-Type\\\'}\\n\\ndef require(ok):\\n    if not ok:\\n        raise ValueError(\\\'STATIC_OBSERVATION_UNPROVEN\\\')\\n\\ndef identity(s):\\n    return (s.st_dev, s.st_ino, s.st_mode, s.st_uid, s.st_gid,\\n            s.st_nlink, s.st_size, s.st_mtime_ns, s.st_ctime_ns)\\n\\ndef routing():\\n    r = subprocess.run([\\\'/usr/bin/systemctl\\\', \\\'--no-pager\\\', \\\'show\\\',\\n        \\\'ouf-policy-token@semantic.service\\\', \\\'--property=ExecStart,Type,User\\\'],\\n        capture_output=True, timeout=15)\\n    require(r.returncode == 0 and len(r.stdout) <= 65536)\\n    fields = {}\\n    for line in r.stdout.decode().splitlines():\\n        key, separator, value = line.partition(\\\'=\\\')\\n        if separator:\\n            require(key not in fields)\\n            fields[key] = value\\n    require(fields.get(\\\'Type\\\') == \\\'oneshot\\\' and fields.get(\\\'User\\\') == \\\'root\\\')\\n    text = fields.get(\\\'ExecStart\\\', \\\'\\\')\\n    exe = re.search(r\\\'\\\\bpath=([^ ;}]+)\\\', text)\\n    argv = re.search(r\\\'argv\\\\[\\\\]=(.*?);\\\', text)\\n    require(text.count(\\\'argv[]=\\\') == 1 and exe and argv and exe.group(1) == \\\'/usr/bin/python3\\\')\\n    args = shlex.split(argv.group(1)); require(args and args[0] == \\\'/usr/bin/python3\\\')\\n    index = 1\\n    while index < len(args) and args[index] in {\\\'-I\\\', \\\'-B\\\', \\\'-u\\\', \\\'-E\\\', \\\'-s\\\', \\\'-S\\\'}:\\n        index += 1\\n    require(index < len(args) and args[index] == str(TARGET))\\n    return tuple(args)\\n\\ndef snapshot(path=TARGET, expected=EXPECTED):\\n    fds = []; entries = []\\n    try:\\n        directory_flags = os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW | os.O_NONBLOCK\\n        root = os.open(\\\'/\\\', directory_flags); fds.append(root)\\n        s = os.fstat(root); require(s.st_uid == 0 and not s.st_mode & 0o022)\\n        parent = root; current = Path(\\\'/\\\')\\n        for part in path.parts[1:-1]:\\n            current /= part\\n            before = os.stat(part, dir_fd=parent, follow_symlinks=False)\\n            require(stat.S_ISDIR(before.st_mode))\\n            custody = (before.st_uid, before.st_gid, stat.S_IMODE(before.st_mode))\\n            require(custody == expected[str(current)])\\n            child = os.open(part, directory_flags, dir_fd=parent); fds.append(child)\\n            require(identity(before) == identity(os.fstat(child)))\\n            entries.append((parent, part, child, identity(before))); parent = child\\n        before = os.stat(path.name, dir_fd=parent, follow_symlinks=False)\\n        require(stat.S_ISREG(before.st_mode) and before.st_uid == before.st_gid == 0\\n                and stat.S_IMODE(before.st_mode) == 0o755 and before.st_nlink == 1\\n                and 0 < before.st_size <= 131072)\\n        fd = os.open(path.name, os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK, dir_fd=parent)\\n        fds.append(fd); require(identity(before) == identity(os.fstat(fd)))\\n        raw = bytearray()\\n        while len(raw) <= 131072:\\n            chunk = os.read(fd, min(16384, 131073 - len(raw)))\\n            if not chunk: break\\n            raw.extend(chunk)\\n        require(len(raw) == before.st_size and identity(before) == identity(os.fstat(fd))\\n                == identity(os.stat(path.name, dir_fd=parent, follow_symlinks=False)))\\n        for parent, name, child, saved in entries:\\n            require(saved == identity(os.fstat(child))\\n                    == identity(os.stat(name, dir_fd=parent, follow_symlinks=False)))\\n        return bytes(raw), identity(before)\\n    finally:\\n        for fd in reversed(fds): os.close(fd)\\n\\ndef redact(raw):\\n    tree = ast.parse(raw); require(sum(1 for _ in ast.walk(tree)) <= 20000)\\n    labels = {}\\n    class Mask(ast.NodeTransformer):\\n        def visit_Dict(self, node):\\n            node.keys = [key if isinstance(key, ast.Constant) and type(key.value) is str\\n                         and key.value in PUBLIC_KEYS else self.visit(key) if key is not None\\n                         else None for key in node.keys]\\n            node.values = [self.visit(value) for value in node.values]; return node\\n        def visit_Constant(self, node):\\n            if node.value is None or type(node.value) is bool: return node\\n            key = (type(node.value).__name__, repr(node.value))\\n            labels.setdefault(key, \\\'__REDACTED_LITERAL_\\\' + str(len(labels) + 1) + \\\'__\\\')\\n            return ast.copy_location(ast.Constant(labels[key]), node)\\n    text = ast.unparse(ast.fix_missing_locations(Mask().visit(tree)))\\n    return {\\\'redactedSource\\\': text[:12000], \\\'redactedSourceTruncated\\\': len(text) > 12000}\\n\\ndef main():\\n    report = {\\\'schema\\\': \\\'ouf.semantic-token-untrusted-static-observation.v1\\\',\\n        \\\'sourceAuthenticationProven\\\': False, \\\'writerAuthorityProven\\\': False,\\n        \\\'outputBindingProven\\\': False, \\\'producerExecuted\\\': False, \\\'serviceMutations\\\': 0,\\n        \\\'protectedFileWrites\\\': 0, \\\'providerCalls\\\': 0, \\\'tokenGrantRequests\\\': 0,\\n        \\\'baselineRefreshed\\\': False, \\\'budgetReset\\\': False, \\\'r12Touched\\\': False,\\n        \\\'runtimeAuthorityIssued\\\': False, \\\'notReleaseAcceptance\\\': True,\\n        \\\'sourceContentBytesRead\\\': 0, \\\'execStartArgumentsPrinted\\\': False,\\n        \\\'environmentValuesPrinted\\\': False, \\\'credentialPathsPrinted\\\': False}\\n    try:\\n        require(os.geteuid() == 0 and __import__(\\\'sys\\\').flags.isolated\\n                and __import__(\\\'sys\\\').dont_write_bytecode)\\n        def deadline(*_): raise ValueError(\\\'STATIC_OBSERVATION_DEADLINE\\\')\\n        signal.signal(signal.SIGALRM, deadline); signal.alarm(60)\\n        command = routing(); raw, seal = snapshot()\\n        report[\\\'sourceContentBytesRead\\\'] += len(raw)\\n        masked = redact(raw)\\n        again, next_seal = snapshot(); report[\\\'sourceContentBytesRead\\\'] += len(again)\\n        require(command == routing() and raw == again and seal == next_seal)\\n        report.update(status=\\\'UNTRUSTED_PRODUCER_STATIC_SOURCE_OBSERVED_NOT_ACCEPTED\\\',\\n            producerSourcePath=str(TARGET), sourceSha256=hashlib.sha256(raw).hexdigest(),\\n            rootOnlyAncestorCustody=False, stableDoubleRead=True,\\n            sourceByteAccountingComplete=True, **masked)\\n        code = 0\\n    except Exception:\\n        report.update(status=\\\'UNTRUSTED_PRODUCER_STATIC_OBSERVATION_BLOCKED\\\',\\n                      reason=\\\'STATIC_OBSERVATION_UNPROVEN\\\', sourceContentBytesRead=None,\\n                      sourceByteAccountingComplete=False); code = 1\\n    finally: signal.alarm(0)\\n    print(\\\'OUF_TOKEN_PRODUCER_STATIC_OBSERVATION=\\\' + json.dumps(report, sort_keys=True))\\n    return code\\n\\nif __name__ == \\\'__main__\\\': raise SystemExit(main())\\n\'\nOBSERVER_HASH=\'b1610dc67b0c40c5243ebdb04c20b6f3981ca1c17f8cd5b6d9fc5de54a6ea365\'\nCODE_HASH="728b4c44d0e24b3c3bfc31769346c0c05752e870e93c096fac1c2897250e5c79"\nINTAKE_HASH="005f6a7afad7d493a52d9b183816fa0346f1bb1a4de5ab4b63c8b0b39f3fb092"\nPARENT=Path("/etc/ouf/deploy-snapshots/semantic-native-v11-intake-"+INTAKE_HASH)\nNAMES=("gated-creation-request.private.json","gate-proposal.json","retained-mount-metadata.private.json","parent-review-reference.json")\nKEYS={"OUF_POLICY_TOKEN_"+v for v in ("CLIENT_ID","ENDPOINT","REQUIRED_SCOPE","RUNTIME_DIR","RUNTIME_GID","SECRET_FILE")}\n\ndef require(ok):\n    if not ok: raise ValueError(\'PRIVATE_BINDING_UNPROVEN\')\n\ndef sha(raw): return hashlib.sha256(raw).hexdigest()\n\ndef identity(s):\n    return (s.st_dev,s.st_ino,s.st_mode,s.st_uid,s.st_gid,s.st_nlink,\n            s.st_size,s.st_mtime_ns,s.st_ctime_ns)\n\ndef private_read(path):\n    require(path.is_absolute() and \'..\' not in path.parts and len(path.parts)<=32)\n    fds=[]; entries=[]\n    try:\n        flags=os.O_RDONLY|os.O_DIRECTORY|os.O_NOFOLLOW|os.O_NONBLOCK\n        parent=os.open(\'/\',flags); fds.append(parent)\n        for part in path.parts[1:-1]:\n            before=os.stat(part,dir_fd=parent,follow_symlinks=False)\n            require(stat.S_ISDIR(before.st_mode) and before.st_uid==0 and not before.st_mode&0o022)\n            child=os.open(part,flags,dir_fd=parent); fds.append(child)\n            require(identity(before)==identity(os.fstat(child)))\n            entries.append((parent,part,child,identity(before))); parent=child\n        before=os.stat(path.name,dir_fd=parent,follow_symlinks=False)\n        require(stat.S_ISREG(before.st_mode) and before.st_uid==0\n                and stat.S_IMODE(before.st_mode)==0o600 and before.st_nlink==1\n                and 0<before.st_size<=2000000)\n        fd=os.open(path.name,os.O_RDONLY|os.O_NOFOLLOW|os.O_NONBLOCK,dir_fd=parent); fds.append(fd)\n        require(identity(before)==identity(os.fstat(fd)))\n        raw=bytearray()\n        while len(raw)<=2000000:\n            chunk=os.read(fd,min(16384,2000001-len(raw)))\n            if not chunk: break\n            raw.extend(chunk)\n        require(len(raw)==before.st_size and identity(before)==identity(os.fstat(fd))\n                ==identity(os.stat(path.name,dir_fd=parent,follow_symlinks=False)))\n        for directory,name,child,seal in entries:\n            require(seal==identity(os.fstat(child))==identity(os.stat(name,dir_fd=directory,follow_symlinks=False)))\n        return bytes(raw)\n    finally:\n        for fd in reversed(fds): os.close(fd)\n\ndef decode(raw):\n    def pairs(rows):\n        result={}\n        for key,value in rows:\n            require(key not in result); result[key]=value\n        return result\n    return json.loads(raw,object_pairs_hook=pairs,parse_constant=lambda _:require(False))\n\ndef plan():\n    require(stat.S_IMODE(PARENT.lstat().st_mode)==0o700 and set(os.listdir(PARENT))==set(NAMES)|{\'intake.json\'})\n    manifest=private_read(PARENT/\'intake.json\'); require(sha(manifest)==INTAKE_HASH)\n    hashes=decode(manifest)[\'fileHashes\']; require(set(hashes)==set(NAMES))\n    files={name:private_read(PARENT/name) for name in NAMES}\n    require({name:sha(raw) for name,raw in files.items()}==hashes)\n    require(sha(files[NAMES[0]])==\'37b517eda22f5997504687222679d458c9478ee66ba5ef2377cf5588ef3f0a9d\')\n    old=decode(files[NAMES[2]]); require(type(old) is list and len(old)==2)\n    seals=[\'edd17c66ebb3c64747bcb69fa17a69380198ae0b2a4dadf86d941473b55dfa02\',\n           \'22ce221e8216648947bd861cb18c8b3c888467d8e2eec8bda057d08a03ce79ed\']\n    require([sha(json.dumps(item[\'sourceMetadata\'],sort_keys=True,separators=(\',\',\':\'),allow_nan=False).encode()) for item in old]==seals)\n    return old,manifest,files\n\ndef parse_config(raw):\n    require(len(raw)<=65536); result={}\n    for line in raw.decode(\'utf-8\').splitlines():\n        line=line.strip()\n        if not line or line.startswith((\'#\',\';\')): continue\n        match=re.fullmatch(r\'([A-Z][A-Z0-9_]*)=(.*)\',line); require(match)\n        key,value=match.groups(); require(key in KEYS and key not in result)\n        value=value.strip()\n        if value.startswith((\'"\',"\'")):\n            require(len(value)>=2 and value[-1]==value[0]); value=value[1:-1]\n        require(not any(c in value for c in (\'\\\\\',\'"\',"\'",\'\\x00\',\'\\r\',\'\\n\')))\n        result[key]=value.strip()\n    require(set(result)==KEYS)\n    require(all(value for key,value in result.items() if key!=\'OUF_POLICY_TOKEN_REQUIRED_SCOPE\'))\n    return result\n\ndef routing():\n    properties=[\'EnvironmentFiles\',\'UnsetEnvironment\',\'RootDirectory\',\'RootImage\',\n                \'BindPaths\',\'BindReadOnlyPaths\',\'TemporaryFileSystem\']\n    r=subprocess.run([\'/usr/bin/systemctl\',\'--no-pager\',\'show\',\'ouf-policy-token@semantic.service\',\n                      \'--property=\'+\',\'.join(properties)],capture_output=True,timeout=15)\n    require(r.returncode==0 and len(r.stdout)<=65536)\n    fields={}\n    for line in r.stdout.decode().splitlines():\n        key,separator,value=line.partition(\'=\')\n        if separator: fields.setdefault(key,[]).append(value)\n    require(all(key in fields and len(fields[key])==1 and not fields[key][0] for key in properties[1:]))\n    require(len(fields.get(\'EnvironmentFiles\',[]))==1)\n    match=re.fullmatch(r\'(/[A-Za-z0-9_./@:-]+) \\(ignore_errors=no\\)\',fields[\'EnvironmentFiles\'][0])\n    require(match); path=Path(match.group(1)); require(\'..\' not in path.parts)\n    return path,fields\n\ndef output_member(raw):\n    tree=ast.parse(raw)\n    config=next(node for node in tree.body if isinstance(node,ast.FunctionDef) and node.name==\'config\')\n    refresh=next(node for node in tree.body if isinstance(node,ast.FunctionDef) and node.name==\'refresh\')\n    assign=next(node for node in config.body if isinstance(node,ast.Assign) and ast.unparse(node.targets[0])==\'runtime_dir\')\n    require(ast.unparse(assign.value)=="Path(required(\'OUF_POLICY_TOKEN_RUNTIME_DIR\'))")\n    returned=next(node.value for node in config.body if isinstance(node,ast.Return)); require(isinstance(returned,ast.Dict))\n    runtime_key=next(k.value for k,v in zip(returned.keys,returned.values) if isinstance(k,ast.Constant) and isinstance(v,ast.Name) and v.id==\'runtime_dir\')\n    directory=next(node for node in refresh.body if isinstance(node,ast.Assign) and ast.unparse(node.targets[0])==\'directory\')\n    require(isinstance(directory.value,ast.Subscript) and ast.unparse(directory.value.value)==\'cfg\'\n            and isinstance(directory.value.slice,ast.Constant) and directory.value.slice.value==runtime_key)\n    calls=[n for n in ast.walk(refresh) if isinstance(n,ast.Call) and ast.unparse(n.func)==\'os.replace\']\n    require(len(calls)==1 and len(calls[0].args)==2)\n    destination=calls[0].args[1]\n    require(isinstance(destination,ast.BinOp) and isinstance(destination.op,ast.Div)\n            and ast.unparse(destination.left)==\'directory\' and isinstance(destination.right,ast.Constant))\n    member=destination.right.value\n    require(type(member) is str and re.fullmatch(\'[A-Za-z0-9_.-]{1,128}\',member) and member not in {\'.\',\'..\'})\n    return member\n\ndef timer_metadata():\n    properties=[\'TimersMonotonic\',\'TimersCalendar\',\'AccuracyUSec\',\'RandomizedDelayUSec\',\'Persistent\',\n                \'LastTriggerUSec\',\'NextElapseUSecMonotonic\',\'NextElapseUSecRealtime\',\'ActiveState\',\'SubState\']\n    result=subprocess.run([\'/usr/bin/systemctl\',\'--all\',\'--no-pager\',\'show\',\n        \'ouf-policy-token@semantic.timer\',\'--property=\'+\',\'.join(properties)],\n        capture_output=True,timeout=15)\n    require(result.returncode==0 and len(result.stdout)<=65536)\n    fields={}\n    for line in result.stdout.decode().splitlines():\n        key,separator,value=line.partition(\'=\')\n        if separator and key in properties: fields.setdefault(key,[]).append(value)\n    return {\'timerPropertiesAllValues\':fields,\n            \'timerRequestedPropertiesAbsent\':[key for key in properties if key not in fields],\n            \'timerObservationIsHistorical\':True}\n\ndef compare(cfg,member,old):\n    runtime=Path(cfg[\'OUF_POLICY_TOKEN_RUNTIME_DIR\'])\n    require(runtime.is_absolute() and \'..\' not in runtime.parts and str(runtime)==cfg[\'OUF_POLICY_TOKEN_RUNTIME_DIR\'])\n    gid=cfg[\'OUF_POLICY_TOKEN_RUNTIME_GID\']; require(re.fullmatch(\'[0-9]{1,10}\',gid))\n    metadata=old[0][\'sourceMetadata\']; binding=old[0][\'binding\']\n    require(len(metadata)==2 and binding[\'RW\'] is False and metadata[0][\'kind\']==\'directory\')\n    retained=Path(binding[\'Source\']); historical=retained/metadata[1][\'path\']\n    return {\'configuredOutputMatchesHistoricalMount0\': runtime/member==historical,\n            \'configuredRuntimeDirectoryMatchesHistoricalMount0\': runtime==retained,\n            \'configuredRuntimeGidMatchesHistoricalMount0\': int(gid)==metadata[0][\'gid\']==metadata[1][\'gid\'],\n            \'clientIdConfigured\': bool(cfg[\'OUF_POLICY_TOKEN_CLIENT_ID\']),\n            \'scopeConfigured\': bool(cfg[\'OUF_POLICY_TOKEN_REQUIRED_SCOPE\']),\n            \'endpointHasHttpsPrefix\': cfg[\'OUF_POLICY_TOKEN_ENDPOINT\'].startswith(\'https://\'),\n            \'factsAreConfigurationCorrespondenceNotIssuerOrWriterAuthority\':True}\n\ndef main():\n    report={\'schema\':\'ouf.semantic-token-private-output-correspondence.v2\',\n        \'sourceAuthenticationProven\':False,\'writerAuthorityProven\':False,\'outputBindingProven\':False,\n        \'runtimeAuthorityIssued\':False,\'notReleaseAcceptance\':True,\'producerExecuted\':False,\n        \'configurationValuesPrinted\':False,\'credentialPathsPrinted\':False,\n        \'referencedSecretFilesOpened\':0,\'mountedTokenFilesOpened\':0,\'delegationKeyFilesOpened\':0,\n        \'serviceMutations\':0,\'protectedFileWrites\':0,\'providerCalls\':0,\'tokenGrantRequests\':0,\n        \'baselineRefreshed\':False,\'budgetReset\':False,\'r12Touched\':False}\n    try:\n        require(os.geteuid()==0 and sys.flags.isolated and sys.dont_write_bytecode)\n        def deadline(*_): raise ValueError(\'DEADLINE\')\n        signal.signal(signal.SIGALRM,deadline); signal.alarm(120)\n        require(sha(OBSERVER_SOURCE)==OBSERVER_HASH)\n        observer=types.ModuleType(\'sealed_static_observer\'); exec(compile(OBSERVER_SOURCE,\'<sealed-observer>\',\'exec\'),observer.__dict__)\n        report.update(timer_metadata()); report[\'phase\']=\'SOURCE_ROUTING_AND_CODE\'\n        command=observer.routing(); code,seal=observer.snapshot(); require(sha(code)==CODE_HASH)\n        member=output_member(code); report[\'phase\']=\'SEALED_PLAN\'; old,manifest,files=plan()\n        report[\'phase\']=\'CONFIGURATION_ROUTING\'\n        path,properties=routing()\n        require(all(path!=Path(item[\'binding\'][\'Source\']) and not path.is_relative_to(Path(item[\'binding\'][\'Source\'])) for item in old))\n        report[\'phase\']=\'CONFIGURATION_READ_AND_PARSE\'; raw=private_read(path); cfg=parse_config(raw)\n        facts=compare(cfg,member,old)\n        report[\'phase\']=\'STABLE_RECHECK\'\n        next_code,next_seal=observer.snapshot(); next_old,next_manifest,next_files=plan()\n        require(code==next_code and seal==next_seal and command==observer.routing())\n        require((path,properties)==routing() and raw==private_read(path)\n                and manifest==next_manifest and files==next_files and old==next_old)\n        report.update(status=\'PRIVATE_OUTPUT_CORRESPONDENCE_OBSERVED_NOT_ACCEPTED\',stableDoubleRead=True,\n                      configurationContentBytesRead=2*len(raw),observedProducerSha256=CODE_HASH,\n                      environmentFileCountVerified=1,unitPropertyMultiplicityVerified=True,\n                      singleDirectProducerCommandVerified=True,phase=\'OBSERVED_NOT_ACCEPTED\',**facts); result=0\n    except Exception:\n        report.update(status=\'PRIVATE_OUTPUT_CORRESPONDENCE_BLOCKED\',reason=\'PRIVATE_BINDING_UNPROVEN\'); result=1\n    finally: signal.alarm(0)\n    print(\'OUF_TOKEN_PRIVATE_OUTPUT_CORRESPONDENCE=\'+json.dumps(report,sort_keys=True)); return result\n\nif __name__==\'__main__\': raise SystemExit(main())\n'
