def metadata(path,binding):
    binding.require(path.is_absolute() and str(path)!='/' and '..' not in path.parts
        and len(path.parts)<=32 and len(str(path))<=4096
        and re.fullmatch('/[A-Za-z0-9_./-]+',str(path)))
    parent=Path('/'); seals=[]; protected=True
    for depth,part in enumerate(path.parts[1:-1],1):
        parent/=part; info=parent.lstat(); seals.append(binding.identity(info))
        protected=protected and info.st_uid==0 and not bool(info.st_mode&0o022)
        if not stat.S_ISDIR(info.st_mode):
            return {'ancestorTraversalComplete':False,'stoppedAtAncestorDepth':depth,
                'ancestorIsSymlink':stat.S_ISLNK(info.st_mode)},seals
    info=path.lstat(); seals.append(binding.identity(info))
    return {'ancestorTraversalComplete':True,'rootProtectedAncestors':bool(protected),
        'regularFile':stat.S_ISREG(info.st_mode),'symlink':stat.S_ISLNK(info.st_mode),
        'uid':info.st_uid,'gid':info.st_gid,'modeOctal':format(stat.S_IMODE(info.st_mode),'04o'),
        'linkCount':info.st_nlink,'fileBytesWithin4096':0<info.st_size<=4096,
        'contentsNotInspected':True},seals

def main():
    report={'schema':'ouf.semantic-token-secret-reference-metadata.v1',
        'credentialReferenceContentsRead':0,'privateKeysRead':0,'referencedSecretFilesOpened':0,
        'mountedTokenFilesOpened':0,'delegationKeyFilesOpened':0,
        'configurationValuesPrinted':False,'credentialPathsPrinted':False,
        'producerExecuted':False,'protectedFileWrites':0,'serviceMutations':0,
        'providerCalls':0,'tokenGrantRequests':0,'baselineRefreshed':False,'budgetReset':False,
        'r12Touched':False,'sourceAuthenticationProven':False,'writerAuthorityProven':False,
        'runtimeAuthorityIssued':False,'notReleaseAcceptance':True,'credentialMaterialTypeInferred':False}
    try:
        assert os.geteuid()==0 and sys.flags.isolated and sys.dont_write_bytecode
        def deadline(*_): raise ValueError('DEADLINE')
        signal.signal(signal.SIGALRM,deadline); signal.alarm(60)
        assert hashlib.sha256(BINDING_SOURCE).hexdigest()==BINDING_HASH
        binding=types.ModuleType('sealed_private_binding')
        exec(compile(BINDING_SOURCE,'<sealed-private-binding>','exec'),binding.__dict__)
        path,properties=binding.routing(); raw=binding.private_read(path); cfg=binding.parse_config(raw)
        reference=Path(cfg['OUF_POLICY_TOKEN_SECRET_FILE']); facts,seals=metadata(reference,binding)
        again,next_seals=metadata(reference,binding)
        assert facts==again and seals==next_seals and (path,properties)==binding.routing()
        assert raw==binding.private_read(path)
        report.update(status='SECRET_REFERENCE_METADATA_OBSERVED_NOT_ACCEPTED',
            referenceMetadata=facts,stableDoubleRead=True,configurationContentBytesRead=2*len(raw)); result=0
    except Exception:
        report.update(status='SECRET_REFERENCE_METADATA_BLOCKED',reason='REFERENCE_METADATA_UNPROVEN'); result=1
    finally: signal.alarm(0)
    print('OUF_TOKEN_SECRET_REFERENCE_METADATA='+json.dumps(report,sort_keys=True)); return result

if __name__=='__main__': raise SystemExit(main())
